class ShippingServiceTest extends TestCase
{
    public function test_free_above_threshold(): void
    {
        config(['shop.free_shipping_threshold' => 75.00]);
        $order = new Order(['shipping_country' => 'ES']);

        $cost = (new ShippingService(new CarrierGateway()))->shippingFor($order, Money::fromFloat(80.00));

        $this->assertSame(0, $cost->cents);
    }

    public function test_flat_rate_below_threshold(): void
    {
        config([
            'shop.free_shipping_threshold' => 75.00,
            'shop.shipping_rates' => ['ES' => 490],
            'shop.default_shipping_cents' => 590,
        ]);
        $order = new Order(['shipping_country' => 'ES']);

        $cost = (new ShippingService(new CarrierGateway()))->shippingFor($order, Money::fromFloat(40.00));

        $this->assertSame(490, $cost->cents);
    }
}

class ShippingService
{
    public function __construct(private readonly CarrierGateway $carrier)
    {
    }

    public function shippingFor(Order $order, Money $base): Money
    {
        $threshold = Money::fromFloat((float) config('shop.free_shipping_threshold'));

        if ($base->isGreaterThan($threshold)) {
            return Money::zero();
        }

        // Dynamic method: CarrierGateway has no flatRateFor() declared.
        $cents = $this->carrier->flatRateFor($order->shipping_country);

        return Money::fromCents((int) $cents);
    }
}

class CarrierGateway
{
    /** @param array<int, mixed> $arguments */
    public function __call(string $name, array $arguments): mixed
    {
        if (str_starts_with($name, 'flatRateFor')) {
            $country = $arguments[0] ?? config('shop.default_country');
            $rates = config('shop.shipping_rates', []);

            return $rates[$country] ?? config('shop.default_shipping_cents');
        }

        throw new BadMethodCallException("Unknown carrier method: {$name}");
    }
}
